import numpy as np,lzma,time,json,hashlib
from architecture import ROOT
p=ROOT/'out/v147/tail.raw.bin';raw=p.read_bytes();assert raw[:8]==b'TAILRAW1';a=np.frombuffer(raw[428:],dtype='<i2').reshape(-1,4);start=time.process_time();unique,index=np.unique(a.view('V8').ravel(),return_inverse=True);values=unique.view('<i2').reshape(-1,4);width=2 if len(unique)<=65536 else 4;codes=index.astype('<u2' if width==2 else '<u4');plain=values.tobytes()+codes.tobytes();encoded=lzma.compress(plain,preset=6,check=lzma.CHECK_CRC32);b=lzma.decompress(encoded);vu=np.frombuffer(b[:values.nbytes],dtype='<i2').reshape(-1,4);ci=np.frombuffer(b[values.nbytes:],dtype=codes.dtype);assert np.array_equal(vu[ci],a);dest=ROOT/'out/v147/tail-dictionary.bin';dest.write_bytes(b'TAILDC01'+raw[8:428]+len(unique).to_bytes(4,'little')+width.to_bytes(4,'little')+encoded);r={'state':'complete','bytes':dest.stat().st_size,'unique_response_vectors':len(unique),'index_bytes':width,'decoded_bytes':len(plain),'lossless_roundtrip':True,'decoded_original_sha256':hashlib.sha256(raw[428:]).hexdigest(),'asset_sha256':hashlib.sha256(dest.read_bytes()).hexdigest(),'cpu_seconds':time.process_time()-start,'scope':'Architecture-only response dictionary; native decoder and total budget pending'};(ROOT/'reports/V147-tail-dictionary.json').write_text(json.dumps(r,indent=2)+'\n');print(json.dumps(r),flush=True)
